 * a and b are arrays of strings; lines are compared by exact string equality.
 * Reading equal/delete entries reconstructs a; equal/insert reconstructs b.
 * Equal entries must form a longest common subsequence: the number of deletes
 * plus inserts equals a.length + b.length - 2 * LCS(a, b).
 * Results must be deterministic. In every maximal region without an equal
 * entry, all deletes precede all inserts. No particular LCS is otherwise required.
 * Neither input may be mutated. Empty arrays and repeated/empty strings work.
 * Small changes to 20,000-line inputs must run well under a second: use a Myers
 * O((N + M) * D) algorithm (linear when D is zero), not an O(N * M) LCS table.
 * Here N/M are input lengths and D is the minimal number of inserts + deletes.
 */
function diffLines(a, b) {
  // Keep only the active diagonals at each distance. The trace is needed to
  // reconstruct the shortest path; no N-by-M table is built.
  const trace = [];
  let previous;
  let distance;
  search: for (distance = 0; distance <= a.length + b.length; distance++) {
    const frontier = new Int32Array(2 * distance + 1);
    for (let diagonal = -distance; diagonal <= distance; diagonal += 2) {
      let x;
      if (distance === 0) {
        x = 0;
      } else if (diagonal === -distance ||
          (diagonal !== distance &&
           previous[diagonal + distance - 2] < previous[diagonal + distance])) {
        x = previous[diagonal + distance];
      } else {
        x = previous[diagonal + distance - 2] + 1;
      }
      let y = x - diagonal;
      while (x < a.length && y < b.length && a[x] === b[y]) {
        x++;
        y++;
      }
      frontier[diagonal + distance] = x;
      if (x >= a.length && y >= b.length) {
        trace.push(frontier);
        break search;
      }
    }
    trace.push(frontier);
    previous = frontier;
  }

  const reversed = [];
  let x = a.length;
  let y = b.length;
  for (let d = distance; d > 0; d--) {
    const diagonal = x - y;
    const frontier = trace[d - 1];
    const insertion = diagonal === -d ||
      (diagonal !== d &&
       frontier[diagonal + d - 2] < frontier[diagonal + d]);
    const previousDiagonal = diagonal + (insertion ? 1 : -1);
    const previousX = frontier[previousDiagonal + d - 1];
    const previousY = previousX - previousDiagonal;
    while (x > previousX && y > previousY) {
      reversed.push({ op: 'equal', line: a[--x] });
      y--;
    }
    if (insertion) {
      reversed.push({ op: 'insert', line: b[--y] });
    } else {
      reversed.push({ op: 'delete', line: a[--x] });
    }
  }
  while (x > 0 && y > 0) {
    reversed.push({ op: 'equal', line: a[--x] });
    y--;
  }
  reversed.reverse();

  // A shortest path can interleave inserts and deletes. Canonicalize each
  // changed region without changing either reconstruction or its length.
  const result = [];
  for (let i = 0; i < reversed.length;) {
    if (reversed[i].op === 'equal') {
      result.push(reversed[i++]);
      continue;
    }
    const start = i;
    while (i < reversed.length && reversed[i].op !== 'equal') i++;
    for (let j = start; j < i; j++) {
      if (reversed[j].op === 'delete') result.push(reversed[j]);
    }
    for (let j = start; j < i; j++) {
      if (reversed[j].op === 'insert') result.push(reversed[j]);
